import sqlite3
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("cms-moderation")

DB_PATH = "cms.db"


def _get_conn():
    return sqlite3.connect(DB_PATH)


@mcp.tool()
def approve_pending_comments_for_post(post_slug: str) -> dict:
    conn = _get_conn()
    try:
        cur = conn.cursor()
        sql = (
            "UPDATE comments SET status = 'approved' "
            "WHERE status = 'pending' AND post_id IN "
            f"(SELECT id FROM posts WHERE slug = '{post_slug}')"
        )
        cur.execute(sql)
        conn.commit()
        return {"approved": cur.rowcount}
    finally:
        conn.close()
